    // Try visiting every city that has not been visited yet
    for (int i = 0; i < n; i++) {
        if ((mask & (1 << i)) == 0) {

            // If city i is not visited 
            // Visit city i and update the mask
            ans = min(ans, cost[curr][i]
                           + totalCost(mask | (1 << i), i, cost, dp));
        }
    }

    return dp[curr][mask] = ans;
}

