    int n = cost.size();
    vector<vector<int>> dp(n, vector<int>(1 << n, -1));

    // Start from city 0, with only city 0
    // visited initially (mask = 1)
    int mask = 1, curr = 0;

    return totalCost(mask, curr, cost, dp);
